import{_ as e,o as r,c as t,a0 as i}from"./chunks/framework.BXmxXpv-.js";const u=JSON.parse('{"title":"研究方向","description":"通过低成本感知、微计算、微通信和端—边—云协同，降低获取有效信息的综合成本，扩大真实世界的感知覆盖。","frontmatter":{"title":"研究方向","description":"通过低成本感知、微计算、微通信和端—边—云协同，降低获取有效信息的综合成本，扩大真实世界的感知覆盖。"},"headers":[],"relativePath":"zh/research.md","filePath":"zh/research.md","lastUpdated":1793673982000}'),l={name:"zh/research.md"};function o(h,a,n,s,c,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="研究方向" tabindex="-1">研究方向 <a class="header-anchor" href="#研究方向" aria-label="Permalink to &quot;研究方向&quot;">​</a></h1><h2 id="研究目标" tabindex="-1">研究目标 <a class="header-anchor" href="#研究目标" aria-label="Permalink to &quot;研究目标&quot;">​</a></h2><p>理解真实世界的状态与变化，需要广泛、连续、可靠的信息输入。我们的长期目标是构建覆盖人类活动及相关自然环境的大规模感知网络，让更多地点能够被持续观测，使人们能够更全面地了解环境、预判变化，并据此作出决策、采取行动。</p><p>实现这一目标，需要让感知终端能够被大规模部署并长期运行。我们关注在满足信息质量、时效性和任务需求的前提下，降低获取单位有效信息的综合成本，包括硬件、计算、通信、供能和维护开销。研究的价值最终体现在能否以可负担的成本，获得更广泛、更丰富、更持久的真实世界信息。</p><h2 id="端—边—云协同" tabindex="-1">端—边—云协同 <a class="header-anchor" href="#端—边—云协同" aria-label="Permalink to &quot;端—边—云协同&quot;">​</a></h2><ul><li><strong>端侧</strong>接触物理世界，完成物理量到数字信息的转换，并进行必要的前端处理。</li><li><strong>边缘侧</strong>汇聚区域内的信息，承担资源允许的初步计算、协同与及时反馈。</li><li><strong>云端</strong>融合跨区域、跨模态和长时间的信息，支持全局建模、分析、预测与推演。</li></ul><p>三者共同承担信息获取、处理与反馈。我们从端侧这一信息源头入手，按任务需求划分功能，减少逐节点重复配置的支撑成本。</p><h2 id="物联网边端体系与智能计算" tabindex="-1">物联网边端体系与智能计算 <a class="header-anchor" href="#物联网边端体系与智能计算" aria-label="Permalink to &quot;物联网边端体系与智能计算&quot;">​</a></h2><p>温度、光照和部分低速振动监测等基础感知任务，单次数据量小，却需要大量节点长期工作。面向这类资源受限的弱终端，我们研究微计算与微通信，精简通用控制、外设操作和无线交互的开销，并通过能量管理使任务执行与可用能量相匹配。</p><p>对于音频、图像和视频等高信息量任务，终端需要承担更多计算。我们进一步探索脉冲神经网络（SNN）与能量控制相结合的音频处理、简化计算阵列和专用可重构执行，以及面向边缘智能的算法与芯片协同设计。</p><h2 id="具身智能感知与交互" tabindex="-1">具身智能感知与交互 <a class="header-anchor" href="#具身智能感知与交互" aria-label="Permalink to &quot;具身智能感知与交互&quot;">​</a></h2><p>研究无源无线感知、物理信号处理，以及图像与视频的结构化表达。Sensor-to-Semantics（S2S）探索在视觉前端组织图元、局部结构和任务所需的证据，让后端按需消费信息，减少不必要的重复计算与传输。</p><p>前端处理需要保留后续任务所需的信息，并通过任务效果验证信息损失的影响。我们将音视频低成本感知作为持续探索的方向，为空间理解和具身交互提供支撑。</p><h2 id="集群协同智能与通信" tabindex="-1">集群协同智能与通信 <a class="header-anchor" href="#集群协同智能与通信" aria-label="Permalink to &quot;集群协同智能与通信&quot;">​</a></h2><p>研究低功耗无线通信、区域信息汇聚、分布式智能与协同决策。利用边缘基础设施与终端之间的资源差异，探索共享支撑功能与轻量无线交互。对于低速基础感知数据及经过前端处理的部分音视频信息，研究与窄带链路相匹配的传输方式，同时兼顾响应时间、可靠性和安全。</p><h2 id="智能信息处理与系统应用" tabindex="-1">智能信息处理与系统应用 <a class="header-anchor" href="#智能信息处理与系统应用" aria-label="Permalink to &quot;智能信息处理与系统应用&quot;">​</a></h2><p>研究数据挖掘、推荐系统和智能数据分析，将多源感知信息组织为可用于建模与决策的表示，并开展原型系统与应用示范。通过具体任务检验信息质量、端到端开销及长期运行能力，逐步连接低成本信息获取与真实场景中的智能应用。</p><h2 id="相关信息" tabindex="-1">相关信息 <a class="header-anchor" href="#相关信息" aria-label="Permalink to &quot;相关信息&quot;">​</a></h2><ul><li><a href="/zh/projects">代表性科研项目</a></li><li><a href="/zh/publication">精选科研论文</a></li><li><a href="/zh/people">实验室成员</a></li><li><a href="/zh/contact">联系我们</a></li></ul>',19)])])}const _=e(l,[["render",o]]);export{u as __pageData,_ as default};
